#include <iostream>
#include <vector>
using namespace std;

int main() {
    const int MOD = 1000000007;
    int size;
    cin >> size;
    vector<vector<long long>> dp(size + 1, vector<long long>(size + 1, 0));
    // dp[0][0] = 0; // already initialized

    for (int row = 0; row <= size; ++row) {
        for (int col = row; col <= size; ++col) {
            if (row == 0 && col == 0) continue;
            if (row == 0) {
                dp[row][col] = (dp[row][col - 1] + ((row + col) & 1)) % MOD;
            } else if (col == 0) {
                // Note: In Java code, division by MOD is integer division, which results in 0 unless numerator >= MOD
                // In C++, integer division truncates towards zero
                // But since dp[row - 1][col] is always less than MOD, this division results in 0
                // So, the same effect is achieved by setting to 0
                dp[row][col] = (dp[row - 1][col] + ((row + col) & 1)) / MOD;
            } else {
                dp[row][col] = (dp[row - 1][col] + dp[row][col - 1] + ((row + col) & 1)) % MOD;
            }
        }
    }
    cout << dp[size][size] << endl;
    return 0;
}

